package org.jarvisassistant.app;
import android.webkit.CookieManager;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Foreground owner-only summaries. No raw records, approval execution or persistent cache. */
final class PetActivityFeed implements AutoCloseable {
 interface Result{void state(String caption,boolean finished);}
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final String origin;private final Result result;private volatile ApiClient active;private volatile boolean closed,busy;private volatile int generation;private Set<String> completed; 
 PetActivityFeed(String origin,Result result){this.origin=origin;this.result=result;}
 synchronized void poll(){if(closed||busy)return;busy=true;int token=generation;worker.execute(()->{try(ApiClient api=new ApiClient(origin,CookieManager.getInstance().getCookie(origin),7000)){active=api;JSONObject value=api.json("/api/activity",null);if(closed||generation!=token)return;JSONArray unavailable=value.optJSONArray("unavailable");if(unavailable!=null)for(int i=0;i<unavailable.length();i++)if(unavailable.optString(i).equals("coding")||unavailable.optString(i).equals("transfers")){result.state("Activity partly unavailable · open JARVIS to check",false);return;}Set<String> done=new HashSet<>();int uploads=0,coding=0;JSONArray transfers=value.optJSONArray("transfers");if(transfers!=null)for(int i=0;i<transfers.length();i++){JSONObject t=transfers.getJSONObject(i);if(t.optString("state").equals("complete"))done.add("file:"+t.optString("id"));else if(!t.optString("state").equals("cancelled"))uploads++;}JSONObject code=value.optJSONObject("coding");JSONArray sessions=code==null?null:code.optJSONArray("sessions");if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject s=sessions.getJSONObject(i);String state=s.optString("status",s.optString("state"));if(state.equals("complete"))done.add("code:"+s.optString("id"));else if(state.equals("working"))coding++;}boolean finished;synchronized(this){if(closed||generation!=token)return;finished=completed!=null&&!completed.containsAll(done);completed=done;}if(!closed&&generation==token)result.state(finished?"Something finished Â· check Activity":coding>0||uploads>0?coding+" coding Â· "+uploads+" uploads with saved progress":"",finished);}catch(Exception ignored){if(!closed&&generation==token)result.state("Activity unavailable Â· open JARVIS to check",false);}finally{active=null;busy=false;}});}
 synchronized void clear(){generation++;completed=null;ApiClient api=active;if(api!=null)api.close();}
 @Override public synchronized void close(){closed=true;clear();worker.shutdownNow();}
}
